package com.shengxu.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.shengxu.entity.MusicTask; import com.shengxu.mapper.MusicTaskMapper; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import java.time.*; import java.util.concurrent.TimeUnit;
@Component
public class MusicTaskScheduler {
 private static final Logger log=LoggerFactory.getLogger(MusicTaskScheduler.class); private final MusicTaskMapper tasks; private final SunoApiService suno; private final TaskProcessor processor; private final StringRedisTemplate redis;
 public MusicTaskScheduler(MusicTaskMapper t,SunoApiService s,TaskProcessor p,StringRedisTemplate r){tasks=t;suno=s;processor=p;redis=r;}
 @Scheduled(fixedDelay=2000) public void run(){if(!suno.configured()||!Boolean.TRUE.equals(redis.opsForValue().setIfAbsent("music:scheduler:lock","1",8,TimeUnit.SECONDS)))return;try{submit();poll();}finally{redis.delete("music:scheduler:lock");}}
 private void submit(){for(MusicTask t:tasks.selectList(new LambdaQueryWrapper<MusicTask>().eq(MusicTask::getSubmitStage,"CREATED").last("LIMIT 5"))){if(tasks.claimSubmit(t.getId())!=1)continue;try{processor.submitted(t,suno.create(t.getPrompt(),t.getStyle(),t.getMood(),t.getVocalType(),t.getLanguage(),t.getLyricsMode(),t.getInputLyrics(),t.getSongTitle(),t.getNegativeTags(),t.getModelVersion(),t.getSourceClipId(),t.getSourceType(),t.getSourceAudioUrl(),t.getSourceTitle(),t.getWeirdness(),t.getStyleWeight(),t.getDuration(),t.getVariety(),t.getAudioWeight(),Integer.valueOf(1).equals(t.getMaxMode()),t.getVoiceId(),t.getSoundType(),t.getSoundBpm(),t.getSoundKey(),Integer.valueOf(1).equals(t.getSoundLoop())));}catch(Exception e){log.warn("music task provider submission uncertain id={} type={} message={}",t.getId(),e.getClass().getSimpleName(),e.getMessage());processor.uncertain(t.getId(),"提交结果待核实，请勿重复创建任务");}}}
 private void poll(){for(MusicTask t:tasks.selectList(new LambdaQueryWrapper<MusicTask>().eq(MusicTask::getStatus,"PROCESSING").eq(MusicTask::getSubmitStage,"SUBMITTED").le(MusicTask::getNextPollAt,LocalDateTime.now()).last("LIMIT 10"))){try{var ids=java.util.Arrays.stream(t.getProviderSongIds().split(",")).filter(x->!x.startsWith("pending:")).toList();if(ids.isEmpty()){processor.uncertain(t.getId(),"上游仅返回占位标识，请人工核实");continue;}processor.pollResult(t,suno.query(ids));}catch(Exception ignored){t.setPollCount(t.getPollCount()+1);t.setNextPollAt(LocalDateTime.now().plusSeconds(Math.min(60,5+t.getPollCount()*3L)));tasks.updateById(t);}}}
}
